#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> col(n + 1);
    int tot = 0, root = 1;
    for (int i = 1; i <= n; ++i) {
        cin >> col[i];
        if (col[i]) { ++tot; root = i; }
    }
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    if (tot <= 1) { cout << 0 << '\n'; return 0; }

    // 显式栈建树，避免 n=1e5 链状数据递归爆栈
    vector<int> parent(n + 1, 0), order;
    order.reserve(n);
    vector<int> st{root};
    parent[root] = -1;
    while (!st.empty()) {
        int u = st.back();
        st.pop_back();
        order.push_back(u);
        for (int v : g[u]) if (v != parent[u]) {
            parent[v] = u;
            st.push_back(v);
        }
    }

    vector<int> cnt(n + 1, 0);
    int ans = 0;
    for (int idx = (int)order.size() - 1; idx >= 0; --idx) {
        int u = order[idx];
        cnt[u] += col[u];
        for (int v : g[u]) if (parent[v] == u) cnt[u] += cnt[v];
        if (cnt[u] > 0 && cnt[u] < tot && col[u] == 0) ++ans;
    }
    cout << ans << '\n';
    return 0;
}
